        pixel_index[14986]=4'd10;
    end
    always @(posedge I_clk)begin
        index_q<=pixel_index[address];
        row_q<=I_y[6:0];
        inside_q<=inside_logo;
        exception_q<=exception_pixel;
        palette_q<=palette[palette_address];
        inside_qq<=inside_q;
        exception_qq<=exception_q;
    end
endmodule
